public class VisibleMotionAudit:MonoBehaviour{const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/ScrollAndFramingRepair/";object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);Color32[] P(DynamicCardView v){var rt=(RenderTexture)F(v,"texture");var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=old;var p=t.GetPixels32();Destroy(t);return p;}IEnumerator Start(){var views=FindObjectsOfType<DynamicCardView>().Where(v=>F(v,"texture")!=null&&(bool)v.GetType().GetMethod("IsVisible",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(v,null)).ToArray();var before=views.Select(P).ToArray();var bones=views.Select(v=>((GameObject)F(v,"model")).GetComponentsInChildren<Transform>(true)).ToArray();var rot=bones.Select(b=>b.Select(t=>t.localRotation).ToArray()).ToArray();yield return new WaitForSecondsRealtime(6);var lines=new List<string>();for(int i=0;i<views.Length;i++){var v=views[i];if(v==null||F(v,"texture")==null)continue;var after=P(v);long delta=0;for(int n=0;n<after.Length;n++)delta+=Math.Abs(after[n].r-before[i][n].r)+Math.Abs(after[n].g-before[i][n].g)+Math.Abs(after[n].b-before[i][n].b);int moving=bones[i].Where((b,j)=>Quaternion.Angle(b.localRotation,rot[i][j])>.001f).Count();lines.Add(F(v,"artId")+" pixels="+delta+" moving="+moving+" animator="+string.Join(";",((GameObject)F(v,"model")).GetComponentsInChildren<Animator>(true).Select(a=>a.enabled+"/"+a.cullingMode+"/"+a.GetCurrentAnimatorStateInfo(0).normalizedTime)));}File.WriteAllLines(W+"bottom-motion-fixed-sweep.txt",lines);Destroy(gameObject);}}
